// Cached directed connections. Topology changes rebuild only nearby entity ports.
(function(root){
'use strict';
const D=[[1,0],[0,1],[-1,0],[0,-1]];
class LogisticsGraph {
 constructor(game){this.game=game;this.nodes=new Set();this.active=new Set();this.nextId=1;this.version=0;this.rebuiltNodes=0}
 node(b,slot,transport=false){const n={id:this.nextId++,entity:b,slot,transport,edges:[],occupiedEpoch:-1};this.nodes.add(n);return n}
 watch(b,slot,n,container=b){n.item=container[slot];Object.defineProperty(container,slot,{enumerable:true,configurable:true,get:()=>n.item,set:value=>{n.item=value;if(value)this.active.add(n);else this.active.delete(n)}});if(n.item)this.active.add(n)}
 add(b){b.graphNodes=[];if(b.type==='junction'){b.horizontalNode=this.node(b,'horizontal',true);b.verticalNode=this.node(b,'vertical',true);b.graphNodes.push(b.horizontalNode,b.verticalNode);this.watch(b,'horizontal',b.horizontalNode,b.channels);this.watch(b,'vertical',b.verticalNode,b.channels)}else if(b.isTransport||b.type==='miner'){b.itemNode=this.node(b,'item',b.isTransport);b.graphNodes.push(b.itemNode);this.watch(b,'item',b.itemNode)}else if(b.type==='smelter'||b.isProcessor){b.outputNode=this.node(b,'output');b.inputNode=this.node(b,'input');b.graphNodes.push(b.outputNode,b.inputNode)}else if(b.type==='depot'||b.type==='turret'){b.inputNode=this.node(b,'input');b.graphNodes.push(b.inputNode)}this.refreshAround(b)}
 receiver(b,from){if(!b)return null;if(b.type==='junction')return this.game.side(b,from)%2===0?b.horizontalNode:b.verticalNode;return b.itemNode||b.inputNode}
 rebuild(n){const b=n.entity;n.edges.length=0;if(n.slot==='input')return;let dirs=b.type==='junction'?(n.slot==='horizontal'?[0,2]:[1,3]):b.type==='router'?[0,1,2,3]:b.type==='splitter'?[(b.dir+3)%4,(b.dir+1)%4]:[b.dir];
 if(b.type==='underground'&&b.mode==='entrance'){if(b.link){const from=[b.x,b.y];n.edges.push({target:b.link,from,direction:b.dir,node:b.link.itemNode})}this.rebuiltNodes++;return}
 for(const direction of dirs){const p=b.size===1?[b.x+D[direction][0],b.y+D[direction][1]]:this.game.port(b),from=[p[0]-D[direction][0],p[1]-D[direction][1]],target=this.game.grid.get(...p);if(target&&!(b.type==='junction'&&target.type==='junction')&&!(['junction','router'].includes(b.type)&&target.type==='belt'&&target.dir===(direction+2)%4))n.edges.push({target,from,direction,node:this.receiver(target,from)})}this.rebuiltNodes++}
 structural(source,edge){const b=edge?.target;if(!b||b.removed||b.type==='miner')return false;const side=this.game.side(b,edge.from);if(b.type==='belt'&&['router','junction'].includes(source.type)&&b.dir===side)return false;if(b.type==='junction'){if(source.type==='junction')return false;const n=side%2===0?b.horizontalNode:b.verticalNode,next=n.edges.find(e=>e.direction===(side+2)%4);return !!next&&next.target.type!=='junction'&&this.structural(b,next)}if(b.type==='splitter')return side===(b.dir+2)%4;if(b.type==='underground')return b.mode==='entrance'?side===(b.dir+2)%4:source===b.link;return b.isTransport||b.isProcessor||b.type==='smelter'||b.type==='depot'||b.type==='turret'}
 updateBelt(b){if(b.type!=='belt')return;let input=0,output=0;for(const edge of b.itemNode.edges)if(this.structural(b,edge))output|=1<<edge.direction;for(let side=0;side<4;side++){const d=D[side],neighbor=this.game.grid.get(b.x+d[0],b.y+d[1]);if(!neighbor)continue;for(const n of neighbor.graphNodes||[])if(n.edges.some(e=>e.target===b&&this.structural(neighbor,e)))input|=1<<side}b.beltInputMask=input;b.beltOutputMask=output;b.beltMask=input|output;const entry=[0,1,2,3].filter(i=>input&(1<<i));b.beltShape=output!==0&&entry.length===1&&entry[0]!==b.dir&&entry[0]!==(b.dir+2)%4?'curve':entry.length===0||output===0?'endpoint':'straight';b.beltSprite='assets/belts/'+b.dir+'-'+b.beltMask+'.svg'}
 refreshAround(b){const affected=new Set([b]);for(let y=b.y-1;y<=b.y+b.size;y++)for(let x=b.x-1;x<=b.x+b.size;x++){const nearby=this.game.grid.get(x,y);if(nearby)affected.add(nearby)}if(b.link)affected.add(b.link);for(const entity of affected)for(const n of entity.graphNodes||[])if(this.nodes.has(n))this.rebuild(n);const visual=new Set(affected);for(const entity of affected)for(const d of D){const neighbor=this.game.grid.get(entity.x+d[0],entity.y+d[1]);if(neighbor)visual.add(neighbor)}for(const entity of visual)this.updateBelt(entity);this.version++}
 remove(b){for(const n of b.graphNodes){this.nodes.delete(n);this.active.delete(n)}this.refreshAround(b)}
 item(n){return n.item}
 clear(n){if(n.slot==='horizontal'||n.slot==='vertical')n.entity.channels[n.slot]=null;else if(n.slot==='output')n.entity.output.shift();else n.entity.item=null}
}
root.Network={LogisticsGraph};if(typeof module!=='undefined')module.exports=root.Network;
})(globalThis);
